use serde::{Deserialize, Serialize};

/// Every FeltDB surface resolves to one of these subjects before authorization.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "kind", content = "id", rename_all = "snake_case")]
pub enum Subject {
    User(String),
    Service(String),
    Workload(String),
    Agent(String),
    Connection(String),
    Worker(String),
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Membership {
    pub subject_id: String,
    pub tenant_id: String,
    pub application_id: Option<String>,
    pub roles: Vec<String>,
    #[serde(default)]
    pub revoked: bool,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct RoleGrant {
    pub role: String,
    pub capabilities: Vec<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AuthorizationRequest<'a> {
    pub subject: &'a Subject,
    pub tenant_id: &'a str,
    pub application_id: Option<&'a str>,
    pub capability: &'a str,
    /// Direct grants are used by machine credentials and narrowly delegated identities.
    pub direct_grants: &'a [String],
    pub memberships: &'a [Membership],
    pub roles: &'a [RoleGrant],
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct AuthorizationDecision {
    pub allowed: bool,
    pub capability: String,
    pub reason: &'static str,
}

impl Subject {
    pub fn id(&self) -> &str {
        match self {
            Self::User(id)
            | Self::Service(id)
            | Self::Workload(id)
            | Self::Agent(id)
            | Self::Connection(id)
            | Self::Worker(id) => id,
        }
    }

    fn can_use_direct_grants(&self) -> bool {
        !matches!(self, Self::User(_))
    }
}

fn grants(capabilities: &[String], required: &str) -> bool {
    capabilities
        .iter()
        .any(|grant| grant == "*" || grant == required)
}

/// Canonical FeltDB authorization decision.
///
/// Human users must pass tenant and application membership before role grants are
/// evaluated. Non-human subjects use credentials or delegated capabilities that
/// are already bound to a tenant/application by their authenticator.
pub fn authorize(request: &AuthorizationRequest<'_>) -> AuthorizationDecision {
    if request.subject.can_use_direct_grants() && grants(request.direct_grants, request.capability)
    {
        return AuthorizationDecision {
            allowed: true,
            capability: request.capability.into(),
            reason: "direct capability grant",
        };
    }

    let memberships: Vec<&Membership> = request
        .memberships
        .iter()
        .filter(|membership| {
            !membership.revoked
                && membership.subject_id == request.subject.id()
                && membership.tenant_id == request.tenant_id
                && match (request.application_id, membership.application_id.as_deref()) {
                    (Some(required), Some(allowed)) => required == allowed,
                    (Some(_), None) => false,
                    (None, None) => true,
                    (None, Some(_)) => true,
                }
        })
        .collect();

    if memberships.is_empty() {
        return AuthorizationDecision {
            allowed: false,
            capability: request.capability.into(),
            reason: "no active membership for resource scope",
        };
    }

    let allowed = memberships
        .iter()
        .flat_map(|membership| membership.roles.iter())
        .any(|role| {
            request
                .roles
                .iter()
                .any(|grant| grant.role == *role && grants(&grant.capabilities, request.capability))
        });
    AuthorizationDecision {
        allowed,
        capability: request.capability.into(),
        reason: if allowed {
            "role grants capability"
        } else {
            "capability not granted"
        },
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn roles() -> Vec<RoleGrant> {
        vec![RoleGrant {
            role: "operator".into(),
            capabilities: vec!["state:read".into(), "workflows:run".into()],
        }]
    }

    #[test]
    fn user_requires_matching_application_membership_and_role() {
        let subject = Subject::User("user_1".into());
        let memberships = vec![Membership {
            subject_id: "user_1".into(),
            tenant_id: "tenant_a".into(),
            application_id: Some("app_a".into()),
            roles: vec!["operator".into()],
            revoked: false,
        }];
        let role_grants = roles();
        let allowed = authorize(&AuthorizationRequest {
            subject: &subject,
            tenant_id: "tenant_a",
            application_id: Some("app_a"),
            capability: "state:read",
            direct_grants: &[],
            memberships: &memberships,
            roles: &role_grants,
        });
        assert!(allowed.allowed);
        let cross_app = authorize(&AuthorizationRequest {
            subject: &subject,
            tenant_id: "tenant_a",
            application_id: Some("app_b"),
            capability: "state:read",
            direct_grants: &[],
            memberships: &memberships,
            roles: &role_grants,
        });
        assert!(!cross_app.allowed);
    }

    #[test]
    fn role_does_not_grant_unlisted_capability() {
        let subject = Subject::User("user_1".into());
        let memberships = vec![Membership {
            subject_id: "user_1".into(),
            tenant_id: "tenant_a".into(),
            application_id: Some("app_a".into()),
            roles: vec!["operator".into()],
            revoked: false,
        }];
        let role_grants = roles();
        let decision = authorize(&AuthorizationRequest {
            subject: &subject,
            tenant_id: "tenant_a",
            application_id: Some("app_a"),
            capability: "members:write",
            direct_grants: &[],
            memberships: &memberships,
            roles: &role_grants,
        });
        assert!(!decision.allowed);
    }

    #[test]
    fn machine_identity_uses_scoped_direct_grants() {
        let subject = Subject::Workload("workload_7".into());
        let grants = vec!["state:read".into()];
        assert!(
            authorize(&AuthorizationRequest {
                subject: &subject,
                tenant_id: "tenant_a",
                application_id: Some("app_a"),
                capability: "state:read",
                direct_grants: &grants,
                memberships: &[],
                roles: &[]
            })
            .allowed
        );
        assert!(
            !authorize(&AuthorizationRequest {
                subject: &subject,
                tenant_id: "tenant_a",
                application_id: Some("app_a"),
                capability: "state:write",
                direct_grants: &grants,
                memberships: &[],
                roles: &[]
            })
            .allowed
        );
    }
}
